-- SQLite views exposing the SYNTH fixture tables (FF_FX_*) under the plan §6 names that agents query.
-- Offline tests and the --fixtures CLI only; the real tables come from db/schema.sql (S01).
DROP VIEW IF EXISTS FF_REF_FORMULATION;
CREATE VIEW FF_REF_FORMULATION AS
  SELECT FORMULATION_ID AS FORM_ID, NAME AS GENERIC, DOSAGE_FORM, STRENGTH, UNIT, NLEM_LEVEL,
         SOURCE, SOURCE_URL, FETCHED_AT, IS_PROXY
  FROM FF_FX_FORMULATIONS;
DROP VIEW IF EXISTS FF_REF_CEILING_PRICE;
CREATE VIEW FF_REF_CEILING_PRICE AS
  SELECT FORMULATION_ID AS FORM_ID, '2025-04-01' AS EFFECTIVE_FROM, CAST(CEILING_PRICE_INR AS REAL) AS CEILING_PRICE,
         CEILING_SO_NO AS SO_NUMBER, 4 AS PARA, SOURCE, SOURCE_URL, FETCHED_AT, IS_PROXY
  FROM FF_FX_FORMULATIONS;
DROP VIEW IF EXISTS FF_REF_FORM_API;
CREATE VIEW FF_REF_FORM_API AS
  SELECT b.FORMULATION_ID AS FORM_ID, f.API_ID, CAST(b.API_G_PER_UNIT AS REAL) * 1000 AS API_MG_PER_UNIT
  FROM FF_FX_BOM_ASSUMPTION b JOIN FF_FX_FORMULATIONS f ON f.FORMULATION_ID = b.FORMULATION_ID;
DROP VIEW IF EXISTS FF_REF_BOM_ASSUMPTION;
CREATE VIEW FF_REF_BOM_ASSUMPTION AS
  SELECT FORMULATION_ID AS FORM_ID, CAST(YIELD AS REAL) AS YIELD, CAST(CONVERSION_COST_INR AS REAL) AS CONVERSION_COST_INR,
         CAST(PACKAGING_COST_INR AS REAL) AS PACKAGING_COST_INR, CAST(FREIGHT_COST_INR AS REAL) AS FREIGHT_COST_INR,
         SOURCE, SOURCE_URL, FETCHED_AT, IS_PROXY
  FROM FF_FX_BOM_ASSUMPTION;
DROP VIEW IF EXISTS FF_REF_API_COST_MONTHLY;
CREATE VIEW FF_REF_API_COST_MONTHLY AS
  SELECT API_ID, MONTH, CAST(COST_PER_KG_INR AS REAL) AS UNIT_VALUE_INR_KG, NULL AS QTY_KG,
         SOURCE, SOURCE_URL, FETCHED_AT, IS_PROXY
  FROM FF_FX_API_COST_MONTHLY;
DROP VIEW IF EXISTS FF_REF_PRODUCER;
CREATE VIEW FF_REF_PRODUCER AS
  SELECT FORMULATION_ID AS FORM_ID, MANUFACTURER_ID, SOURCE AS EVIDENCE_SOURCE FROM FF_FX_PRODUCERS;
DROP VIEW IF EXISTS FF_MM_MARA;
CREATE VIEW FF_MM_MARA AS SELECT MATNR, MAKTX, FORMULATION_ID AS FORM_ID, MEINS, VED, COLD_CHAIN FROM FF_FX_MARA;
DROP VIEW IF EXISTS FF_MM_MCHB;
CREATE VIEW FF_MM_MCHB AS SELECT MATNR, WERKS, LGORT, CHARG, CAST(CLABS AS REAL) AS CLABS, VFDAT, QUARANTINE FROM FF_FX_MCHB;
